import threading

class ThreadSafeCounter:
    def __init__(self):
        self._counts = {}
        self._lock = threading.Lock()

    def increment(self, key, delta=1):
        with self._lock:
            self._counts[key] = self._counts.get(key, 0) + delta

    def snapshot(self):
        with self._lock:
            return dict(self._counts)

