import threading, time

class RateLimiter:
    def __init__(self, calls_per_second):
        self.min_interval = 1.0 / calls_per_second
        self._lock = threading.Lock()
        self._last = 0.0

    def wait(self):
        with self._lock:
            now = time.monotonic()
            wait_for = self._last + self.min_interval - now
            if wait_for > 0:
                time.sleep(wait_for)
            self._last = time.monotonic()

def download_all(urls, fetch, workers=4, rate=10):
    limiter = RateLimiter(rate)
    results = {}
    lock = threading.Lock()

    def worker(url):
        limiter.wait()
        body = fetch(url)
        with lock:
            results[url] = body

    threads = [threading.Thread(target=worker, args=(url,)) for url in urls]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    return results

