import threading

class Timer:
    def __init__(self, delay, callback, *args):
        self._event = threading.Event()
        self._thread = threading.Thread(target=self._run, args=(delay, callback, args), daemon=True)
        self._result = None

    def start(self):
        self._thread.start()
        return self

    def _run(self, delay, callback, args):
        if self._event.wait(delay):
            return
        self._result = callback(*args)

    def cancel(self):
        self._event.set()

    def join(self, timeout=None):
        self._thread.join(timeout)
        return self._result

