from concurrent.futures import ThreadPoolExecutor, as_completed

def run_as_completed(worker, items, timeout=None):
    tagged = []
    with ThreadPoolExecutor(max_workers=4) as pool:
        future_map = {pool.submit(worker, item): item for item in items}
        for future in as_completed(future_map, timeout=timeout):
            tagged.append((future_map[future], future.result()))
    return tagged

