import threading, time

class StoppableWorker:
    def __init__(self):
        self._stop = threading.Event()
        self.handled = 0

    def request_stop(self):
        self._stop.set()

    def run(self, items, delay=0):
        for item in items:
            if self._stop.is_set():
                break
            self.handled += 1
            if delay:
                time.sleep(delay)
        return self.handled

