threading.Timer(0.05, worker.request_stop).start()
print(worker.run(range(1000), delay=0.01))

import threading

def per_thread_counters(n_calls, n_threads):
    local = threading.local()
    counts = {}
    lock = threading.Lock()

    def bump():
        local.count = getattr(local, 'count', 0) + 1
        return local.count

    def worker(name):
        for _ in range(n_calls):
            bump()
        with lock:
            counts[name] = local.count

    threads = [threading.Thread(target=worker, args=(f't{i}',)) for i in range(n_threads)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    return counts

