import threading, tempfile, os

def thread_safe_log(path, lines):
    lock = threading.Lock()

    def writer(batch):
        with lock, open(path, 'a', encoding='utf-8') as f:
            for line in batch:
                f.write(line + '\n')

    chunks = [lines[i::3] for i in range(3)]
    threads = [threading.Thread(target=writer, args=(chunk,)) for chunk in chunks]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    with open(path) as f:
        return len(f.read().splitlines())

