import threading

def run_with_timeout(fn, timeout, *args, **kwargs):
    outcome = {}
    def target():
        try:
            outcome['result'] = fn(*args, **kwargs)
        except Exception as exc:
            outcome['error'] = exc
    thread = threading.Thread(target=target, daemon=True)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        raise TimeoutError('function did not finish within the timeout')
    if 'error' in outcome:
        raise outcome['error']
    return outcome['result']

